const CARDS = [{"front": "Trade capital expense for variable expense", "back": "Paying hourly instead of buying hardware swaps fixed upfront spending for usage-based spending."}, {"front": "Economies of scale", "back": "Aggregating usage across many customers to lower unit prices for everyone."}, {"front": "Go global in minutes", "back": "Deploying infrastructure to multiple AWS Regions worldwide with a few clicks."}, {"front": "Shared Responsibility Model", "back": "AWS manages the security OF the cloud; the customer manages security IN the cloud."}, {"front": "Amazon S3", "back": "Object storage service used for storing and retrieving any amount of data."}, {"front": "AWS Lambda", "back": "Serverless compute service that runs code in response to events."}, {"front": "Amazon EC2", "back": "Provides resizable compute capacity in the cloud."}, {"front": "Amazon RDS", "back": "Managed relational database service."}, {"front": "Amazon DynamoDB", "back": "Managed NoSQL key-value database service."}, {"front": "AWS IAM", "back": "Manages access to AWS resources through users, groups, and roles."}, {"front": "AWS CloudWatch", "back": "Monitoring and observability service for AWS resources."}, {"front": "AWS CloudTrail", "back": "Records API calls and account activity for auditing."}, {"front": "AWS Trusted Advisor", "back": "Provides recommendations to optimize cost, performance, and security."}, {"front": "AWS Organizations", "back": "Centralized management of multiple AWS accounts."}, {"front": "Amazon VPC", "back": "Provides a logically isolated section of the AWS Cloud."}, {"front": "AWS Shield", "back": "Managed DDoS protection service."}, {"front": "AWS WAF", "back": "Web Application Firewall that protects web apps from common exploits."}, {"front": "AWS KMS", "back": "Managed service for creating and controlling encryption keys."}, {"front": "AWS Secrets Manager", "back": "Helps protect secrets like database credentials."}, {"front": "AWS Budgets", "back": "Sets custom budgets that alert you when costs exceed thresholds."}, {"front": "Availability Zone", "back": "One or more isolated data centers within an AWS Region, connected by low-latency private links; the unit of failure isolation."}, {"front": "AWS Region", "back": "A physical geographic location with multiple, isolated Availability Zones; the level at which you choose where workloads live."}, {"front": "Edge location", "back": "A CloudFront cache site closer to end users than any Region — content is served from the nearest edge for lower latency."}, {"front": "Six pillars of the Well-Architected Framework", "back": "Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability."}, {"front": "Elasticity", "back": "Infrastructure that automatically grows and shrinks with demand, so you pay only for what the workload actually needs."}, {"front": "Amazon CloudFront", "back": "AWS's global CDN: caches content at edge locations worldwide for low-latency delivery."}, {"front": "Amazon Route 53", "back": "Managed DNS service — domain registration, name resolution, and routing policies like weighted or latency-based."}, {"front": "AWS Direct Connect", "back": "A private, dedicated physical network link from your data center into AWS — bypasses the public internet."}, {"front": "Site-to-Site VPN", "back": "Encrypted IPsec tunnel over the public internet connecting an on-premises network to a VPC — faster to set up than Direct Connect."}, {"front": "NAT gateway", "back": "Lets instances in a private subnet make outbound internet connections without being reachable from the internet."}, {"front": "Security group vs Network ACL", "back": "Security groups are instance-level, stateful firewalls (allow rules only); NACLs are subnet-level, stateless, and evaluate numbered allow/deny rules."}, {"front": "Amazon EBS", "back": "Block storage volumes attached to EC2 instances — like a virtual hard disk, one volume per instance, snapshot to S3."}, {"front": "Amazon EFS", "back": "Elastic file system — shared POSIX file storage mountable by many instances simultaneously across AZs."}, {"front": "Amazon FSx", "back": "Fully managed third-party file systems: FSx for Windows File Server, FSx for Lustre (HPC), and others."}, {"front": "S3 Standard-IA", "back": "Infrequent Access storage class: cheaper per GB than Standard, with a per-GB retrieval fee — for data accessed rarely but needed quickly."}, {"front": "S3 lifecycle policy", "back": "Automatic transition of objects between storage classes (or expiration) based on their age — no operator involvement."}, {"front": "Amazon Aurora", "back": "AWS's MySQL/PostgreSQL-compatible relational engine with storage auto-scaling, replication, and better performance at the same price point."}, {"front": "Amazon Redshift", "back": "Managed petabyte-scale data warehouse for analytics and OLAP workloads — columnar storage, not transactional."}, {"front": "Amazon ElastiCache", "back": "Managed in-memory cache (Redis or Memcached) to reduce database read load and lower latency."}, {"front": "Amazon SQS", "back": "Managed message queuing — decouples producers from consumers; messages are pulled (polled) by one consumer."}, {"front": "Amazon SNS", "back": "Managed publish/subscribe messaging — pushes notifications to many subscribers at once, including email, SMS, and SQS queues."}, {"front": "Amazon EventBridge", "back": "Serverless event bus that routes events between AWS services and applications based on rules."}, {"front": "AWS Step Functions", "back": "Serverless workflow orchestration — chains Lambda functions and other services into visual state machines."}, {"front": "Amazon ECS vs EKS", "back": "ECS is AWS's own container orchestrator; EKS runs certified Kubernetes with AWS managing the control plane."}, {"front": "AWS Elastic Beanstalk", "back": "PaaS that automatically provisions capacity, load balancing, and health monitoring from your application code — you keep control of the resources."}, {"front": "AWS Snowball / Snowball Edge", "back": "Physical appliances for transferring terabytes to petabytes of data into or out of AWS when the network is too slow."}, {"front": "AWS Outposts", "back": "AWS-designed hardware installed in a customer's own data center running native AWS services for low latency or data residency."}, {"front": "Amazon GuardDuty", "back": "Continuous threat detection using ML on CloudTrail, VPC flow logs, and DNS logs to flag compromised credentials or instances."}, {"front": "Amazon Inspector", "back": "Automated vulnerability management — continuous CVE scanning of EC2 instances and container images."}, {"front": "Amazon Macie", "back": "Uses ML to discover and classify sensitive data (PII) stored in Amazon S3."}, {"front": "AWS Security Hub", "back": "Consolidates security findings from GuardDuty, Inspector, Macie, and partners into one pane, scored against standards like CIS."}, {"front": "AWS Artifact", "back": "Self-service portal to download AWS compliance reports and sign agreements (e.g. PCI, HIPAA)."}, {"front": "IAM Identity Center", "back": "Workforce single sign-on across multiple AWS accounts — connect a corporate directory once, grant access everywhere."}, {"front": "Amazon Cognito", "back": "Identity management for customer-facing applications: sign-up, sign-in, and federated identities for millions of end users."}, {"front": "Multi-factor authentication (MFA)", "back": "Requires a second factor — hardware fob or virtual authenticator app one-time code — in addition to the password."}, {"front": "Principle of least privilege", "back": "Grant only the permissions required to perform a task — nothing more, starting from zero access."}, {"front": "IAM role vs IAM user", "back": "A role issues temporary credentials assumed by workloads or users; a user has permanent long-lived credentials (password/access keys)."}, {"front": "Encryption in transit", "back": "Protects data moving over the network, typically TLS/HTTPS — present at every AWS service endpoint."}, {"front": "Encryption at rest", "back": "Protects stored data (S3, EBS, RDS) using keys — with AWS KMS managing key creation, policies, and CloudTrail-logged usage."}, {"front": "Amazon S3 default encryption", "back": "Every new object is encrypted automatically with SSE-S3 at no extra cost — no configuration needed."}, {"front": "On-Demand Instances", "back": "Pay-per-hour/second compute with no commitment — highest price, maximum flexibility, ideal for spiky or short workloads."}, {"front": "Spot Instances", "back": "Spare AWS capacity at up to 90% off — can be reclaimed with two minutes' notice; for fault-tolerant or interruptible work."}, {"front": "Reserved Instances / Savings Plans", "back": "1- or 3-year commitments in exchange for large discounts (up to 72%) — for steady, predictable workloads."}, {"front": "Data transfer pricing", "back": "Inbound traffic is free; you pay for outbound to the internet and inter-AZ traffic — intra-AZ and inter-region vary."}, {"front": "AWS Cost Explorer", "back": "Visualizes and analyzes historical and current spend, forecasts up to 12 months, filters by service/tags."}];
